#!/usr/bin/env bash
# Round 300 claims (run from store/). Before A edits, output must equal b-round-299/claims-300-output.txt.
# After A's change, allowed deltas = b-round-299/claims-300-after-sketch.txt plus K1/K2/K3 as listed in current-task.md.
L=${CLAIMS_LOOP:-../tmp/studio-real-loop}
A=app/components/arrangement
LIB=$A/ArrangementLibrary.tsx
MM=$A/ArrangementMarkerMenu.tsx
LM=$A/ArrangementLibraryMenu.tsx
K=app/data/studio-lab-links.ts
SH=app/lib/arrangement/shortcuts.ts
ST=app/lib/arrangement/strings.ts
T=app/lib/arrangement/__tests__
D=docs/implementation/2026/quarter-IV/220-studio-link-deep-link.md
echo "K1 HEAD $(git rev-parse --short HEAD 2>/dev/null); gate299 $(python3 -c "import json;g=json.load(open('$L/gates/gate-round-299.json'));print(g['status'], g['commit'][:7])")"
echo "K2 status lines $(git status --short --untracked-files=all 2>/dev/null | wc -l)"
echo "K3 frozen $(wc -l < $L/b-round-299-r300-tree-sha256.txt) rc $(sha256sum -c --quiet $L/b-round-299-r300-tree-sha256.txt >/dev/null 2>&1; echo $?)"
for f in app/routes/studio.\$productId.tsx app/routes/api.studio-token.ts app/routes/account.downloads.tsx app/lib/auth.ts app/contexts/AuthContext.tsx app/lib/firebase.client.ts app/services/api/client.ts; do echo "K4 $f $(grep -cF "  $f" $L/b-round-299-r300-tree-sha256.txt)"; done
echo "K5 library: role=option $(grep -c 'role="option"' $LIB); onContextMenu $(grep -c 'onContextMenu' $LIB); ContextMenu key $(grep -c "'ContextMenu'" $LIB); F10 $(grep -c "'F10'" $LIB); selectLibraryOption defs $(grep -c 'const selectLibraryOption = ' $LIB); preview switch in select $(grep -c 'startLibraryPreview(sourceId, 0);' $LIB); title={source.title} $(grep -c 'title={source.title}' $LIB); aria-haspopup $(grep -c 'aria-haspopup' $LIB)"
echo "K6 SWEEP contextmenu in app/** non-test: $(grep -rniE 'contextmenu' app --include=*.ts --include=*.tsx | grep -v __tests__ | sed 's/:.*//' | sort | uniq -c | tr -s ' ' | tr '\n' ';')"
echo "K7 marker menu: Enter-or-Space branch $(grep -c "event.key === 'Enter' || event.key === ' '" $MM); window blur close $(grep -c "addEventListener('blur', closeOnWindowChange)" $MM); no refocus on window (row) $(grep -c "reason !== 'window'" $A/ArrangementMarkerRow.tsx); item class $(grep -c "^  'flex h-7 w-full items-center gap-2 whitespace-nowrap rounded-sm px-2 text-left text-xs text-foreground hover:bg-elevated';" $MM)"
echo "K8 shortcuts: library ids $(grep -oE "id: 'library-[a-z-]+'" $SH | tr '\n' ' '); test id list library-preview $(grep -c "^  'library-preview',$" $T/shortcuts.test.ts); sheet per-row text loop $(grep -c 'getAllByText(expected.action), expected.id).toHaveLength(1)' $T/shortcut-sheet-ui.test.tsx)"
echo "K9 PNR2: name $(grep -c 'PNR2: rounded-panel appears only on the nine panel sites' $T/panel-radius-ui.test.tsx); MarkerMenu count line $(grep -c "'components/arrangement/ArrangementMarkerMenu.tsx': 1," $T/panel-radius-ui.test.tsx); MENU_ROW entries $(grep -c "name: '[A-Z_]*MENU_ITEM_CLASS'" $T/panel-radius-ui.test.tsx); LibraryMenu $(grep -c 'ArrangementLibraryMenu' $T/panel-radius-ui.test.tsx)"
echo "K10 strings: ST49 exact-keys $(grep -c 'expect(Object.keys(studioLibraryPanelStrings).sort()).toEqual(' $T/strings.test.ts); studioLibraryMenuStrings $(grep -c 'export const studioLibraryMenuStrings' $ST)"
echo "K11 links/demo: exports $(grep -oE 'export (const|function) [A-Za-z_]+' $K | awk '{print $3}' | tr '\n' ' '); map entry $(grep -c "\['middle-east', 'demo-middle-east'\]" $K); demo first id $(grep -m1 -oE "id: 'demo-[a-z-]+'" app/data/studio-lab-demo.ts); title $(grep -c "title: 'Middle East — public preview'" app/data/studio-lab-demo.ts); hero-music source $(grep -c "id: 'demo-hero-music'" app/data/studio-lab-demo.ts); product route $(test -f 'app/routes/products.$handle.tsx' && echo yes)"
echo "K12 doc 220: l.4 $(sed -n 4p $D); TODO STUDIO-LINK-b line $(grep -c 'STUDIO-LINK-b (რაუნდი 300)' $D); 'Completed (C round 300 PASS)' $(grep -c 'Completed (C round 300 PASS)' $D); VS rows $(grep -c 'VS1' $D); In Progress (stage hits in docs/implementation $(grep -rln 'In Progress (stage' docs/implementation | wc -l)"
echo "K13 SWEEP new tokens in app/** perf/** e2e/**: $(grep -rnE 'arrangement-library-menu|library-view-in-store|View in store|ArrangementLibraryMenu|studioLibraryMenuStrings|getStudioLabProductHref|resolveStudioLabProductHandle|LIBRARY_MENU_ITEM_CLASS|data-library-menu-action' app perf e2e 2>/dev/null | wc -l)"
echo "K14 SWEEP menu role counts in tests: $(grep -rnE "(get|query|find)AllByRole\('menu(item)?'" app perf e2e 2>/dev/null | wc -l); role=menu queries $(grep -rlE "ByRole\('menu'" app/**/__tests__ app/lib/arrangement/__tests__ 2>/dev/null | sort -u | wc -l)"
echo "K15 L50 focus-origin grep on granted component files: $(for f in $LIB $LM; do [ -f $f ] && echo -n "$(basename $f)=$(grep -cE 'onPointerDown(Capture)?|onBlur|settleEditor\(|\.focus\(|^\s*\{[^}]*(\.map\(|&&|\?)' $f) "; done)"
echo "K16 studio window keydown: bubble listener $(grep -c "window.addEventListener('keydown', handleKeyDown);" $A/StudioWorkspace.tsx); capture export marker $(grep -c "window.addEventListener('keydown', markExportKeyEvent, true);" $A/StudioWorkspace.tsx); sheet capture $(grep -c "window.addEventListener('keydown', handleSheetKeyDown, true);" $A/ArrangementShortcutSheet.tsx)"
echo "K17 focus ring: STUDIO_FOCUS_RING_INSET_CLASS $(grep -c 'STUDIO_FOCUS_RING_INSET_CLASS' $LIB); global focus-visible lines in app/styles/app.css $(grep -c "focus-visible" app/styles/app.css)"
echo "K18 lines: library $(wc -l < $LIB) links $(wc -l < $K) shortcuts $(wc -l < $SH) strings $(wc -l < $ST) shortcuts.test $(wc -l < $T/shortcuts.test.ts) panel-radius $(wc -l < $T/panel-radius-ui.test.tsx) doc220 $(wc -l < $D) librarymenu $([ -f $LM ] && wc -l < $LM || echo absent) vs-test $([ -f $T/studio-link-view-in-store-ui.test.tsx ] && wc -l < $T/studio-link-view-in-store-ui.test.tsx || echo absent)"
echo "K19 B artifacts: $(for p in sketch-ArrangementLibrary.tsx.txt sketch-ArrangementLibraryMenu.tsx.txt sketch-studio-lab-links.ts.txt sketch-strings.ts.txt sketch-shortcuts.ts.txt sketch-shortcuts.test.ts.txt sketch-panel-radius-ui.test.tsx.txt sketch-studio-link-view-in-store-ui.test.tsx.txt sketch-220-studio-link-deep-link.md.txt sketch.patch.txt sketch-covering-run.log sketch-covering-run-final.log sketch-tsc.log covering-files.txt run-mutant.sh mutants/summary.txt probe/menu-probe.cjs probe/menu-sketch.json probe/head-premise.txt probe/errors-probe.txt im24-sketch-alone.txt probe/space-preview-probe.cjs probe/space-preview-sketch.json; do test -f $L/b-round-299/$p && echo -n 'ok ' || echo -n "MISSING:$p "; done)"
echo "K20 outside-press swallow: marker menu $(grep -c 'armGridMenuDismissClickSwallow(window);' $MM) grid menu $(grep -c 'armGridMenuDismissClickSwallow' $A/ArrangementGridMenu.tsx); marker item class has focus token $(grep -A1 'MARKER_MENU_ITEM_CLASS =' $MM | grep -c 'focus')"
